"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$adb='"'D:\\Downloads\\搞机工具箱11.0.1\\adb.exe'
"'$sn=@('"'-s','AVNS023705001888')
"'$zip='"'C:\\Users\\hzq00\\Downloads\\HONOR_VER_AN10_CODEX_STAGE2_EXECUTION_PACKAGE.zip'
"'$entry='"'HONOR_VER_AN10_CODEX_STAGE2_EXECUTION_PACKAGE/03_PACKAGE_POLICY_SEED.tsv'
"'$outDir='"'C:\\Users\\hzq00\\Documents\\Codex\\2026-08-22\\c-program-files-x86-honorsuite\\work\\stage2_20260823-000955\\adjudication\\A03'

# --- facts (read-only) ---
"'$disabledU0 = @(& $adb @sn shell pm list packages -d --user 0) | ForEach-Object { if ($_ -match '"'"'^package:(.+)$'"') { "'$matches[1] } }
$disabledU128 = @(& $adb @sn shell pm list packages -d --user 128) | ForEach-Object { if ($_ -match '"'"'^package:(.+)$'"') { "'$matches[1] } }
$wl = @(& $adb @sn shell dumpsys deviceidle whitelist)
$userWL = @($wl | Where-Object { $_ -match '"'"'^user,'"' } | ForEach-Object { "'$_.Trim() })
$wlPkg = @{}
foreach ($line in $userWL) { if ($line -match '"'"'^user,([''^,]+),('"\\d+)"'$'"') { "'$wlPkg[$matches[1]] = $matches[2] } }
$netpol = (& $adb @sn shell cmd netpolicy list restrict-background-blacklist) -join '"' '
"'$uidPkg = @{ '"'10369' = 'io.github.sds100.keymapper' }
"'$netpolUid = if ($netpol -match '"'UIDs:\\s*(\\d+)') { "'$matches[1] } else { '"'' }

# --- seed ---
"'$seedRaw = & tar -xOf $zip $entry
$seedLines = @($seedRaw) | Where-Object { $_ -and $_ -notmatch '"'"'^package'"\\t' } 
"'$rows = New-Object System.Collections.Generic.List[string]
$header = "package`tlayer`tseed_policy`tstatus`ts14_state(00:21)`tnow_state(00:31)`tevidence`trecommendation"
$rows.Add($header)

function Add-Row($pkg,$layer,$pol,$status,$s14,$now,$ev,$rec) {
  $script:rows.Add(("$pkg`t$layer`t$pol`t$status`t$s14`t$now`t$ev`t$rec"))
}

foreach ($line in $seedLines) {
  $f = $line -split "`t"
  if ($f.Count -lt 3) { continue }
  $pkg=$f[0]; $layer=$f[1]; $pol=$f[2]; $note=if ($f.Count -gt 3) { $f[3] } else { '"'' }
  "'$inWl = $wlPkg.ContainsKey($pkg)
  $inD0 = $pkg -in $disabledU0
  $inD128 = $pkg -in $disabledU128
  $now = '"'enabled=0(默认)'
  if ("'$inD0) { $now = '"'enabled=3(disabled-user)' } elseif ("'$pkg -eq '"'com.android.devicelockcontroller') { "'$now = '"'enabled=2(disabled)' }
  if ("'$inD128) { $now += '"';u128=disabled(2)' }
  if ("'$inWl) { $now += '"';userWL=yes(uid '+"'$wlPkg[$pkg]+'"')' }
  "'$s14 = '"'同now'
  switch -Regex ("'$pol) {
    '"'"'^KEEP_ALREADY_DISABLED$'"' {
      if ("'$inD0) { Add-Row $pkg $layer $pol '"'COMPLETED' "'$s14 $now '"'user0 enabled=3 保持' '保持禁用；不得 re-enable 或重复 disable' }
      else { Add-Row "'$pkg $layer $pol '"'DRIFT' "'$s14 $now '"'应为 disabled-user，当前未禁用' '记录偏差，先确认来源' }
    }
    '"'^UAD_DISABLE_WAVE_U1$|''^UAD_DISABLE_WAVE_U2$|''^UAD_DISABLE_CONDITIONAL_U3$'"' {
      if ("'$inD0) { Add-Row $pkg $layer $pol '"'COMPLETED' "'$s14 $now '"'已在目标禁用态（origin 需确认）' '保持；勿重复 disable' }
      else { Add-Row "'$pkg $layer $pol '"'PENDING' "'$s14 $now '"'未执行：enabled=0 默认态' '执行波次未运行；执行前需过 S20 闸门' }
    }
    '"'^UNINSTALL_CANDIDATE$'"' {
      Add-Row "'$pkg $layer $pol '"'GATED' "'$s14 $now '"'仍安装；S20 BLOCK 未放行卸载' '仅经 L3/L4 裁定后执行；当前禁止重复尝试' 
    }
    '"'^NMB_AUTO$'"' {
      if ("'$inWl) {
        if ($pkg -eq '"'com.eg.android.AlipayGphone') { Add-Row "'$pkg $layer $pol '"'SYSTEM_RECOVERED' 'userWL=yes' "'$now '"'重启后系统重加 whitelist（01_CURRENT_STATE 已豁免，owner unknown）' '保持 Unrestricted，不建立对抗循环；记录 owner' }
        elseif ("'$pkg -eq '"'com.bilibili.app.in') { Add-Row "'$pkg $layer $pol '"'SYSTEM_RECOVERED' 'userWL=yes(00:18 新增)' "'$now '"'S14 复核期间被外部加入 userWL(56→57)，00:31 仍在' '先识别 owner/并发写者；若需 Auto 再一次性移除并记录；不得盲目循环' }
        else { Add-Row "'$pkg $layer $pol '"'DRIFT' "'$s14 $now '"'目标 Auto 但当前 userWL 存在' '识别来源后处置；勿对抗性重复操作' }
      } else {
        Add-Row "'$pkg $layer $pol '"'COMPLETED' "'$s14 $now '"'AppOps=default(allow)，不在 userWL → Auto 有效' '无操作；注意显式 allow 可能已被系统重置为 default（S14 §4）'
      }
    }
    '"'^NMB_REDUCED$|''^NMB_REDUCED_IF_IDLE$'"' {
      if ("'$inWl) { Add-Row $pkg $layer $pol '"'DRIFT' 'userWL=no' "'$now '"'userWL 新增（00:21 后），与 Reduced 目标冲突' '识别 owner；执行 Reduced 前须先移除白名单并记录' }
      else { Add-Row "'$pkg $layer $pol '"'PENDING' "'$s14 $now '"'AppOps=default(allow)，未 Reduced' '尚未执行 Auto→Reduced；执行前检查 FGS/特殊角色' }
    }
    '"'^NMB_KEEP$'"' {
      if ("'$pkg -eq '"'io.github.sds100.keymapper') {
        Add-Row "'$pkg $layer $pol '"'CONFLICT' 'userWL=yes' "'$now '"'userWL=yes 但 netpolicy 后台数据黑名单 UID 10369 并存' '确认来源；白名单与黑名单二选一，禁止重复叠加'
      } elseif ("'$inWl) {
        Add-Row $pkg $layer $pol '"'COMPLETED' "'$s14 $now '"'userWL=yes，与 KEEP 相符' '保持；无操作'
      } else {
        Add-Row "'$pkg $layer $pol '"'COMPLETED' "'$s14 $now '"'无需白名单；enabled 正常' '保持；无操作'
      }
    }
    '"'^REVIEW$'"' {
      "'$extra = if ($inWl) { '"'；当前在 userWL' } else { '' }
      Add-Row "'$pkg $layer $pol '"'PENDING' "'$s14 $now '"'种子未定；待裁定'+"'$extra '"'裁定后再动作；白名单项（andpodsop/dts/fakelocation/tide）倾向 KEEP（S14 建议）'
    }
    '"'^KEEP$'"' {
      if ("'$inD0) {
        if ($pkg -eq '"'com.android.devicelockcontroller') { Add-Row "'$pkg $layer $pol '"'DRIFT' 'enabled=2;AppOps=allow;WL残留' "'$now '"'disabled(2)+AppOps allow+白名单残留，与 KEEP 不符' '记录来源；残留无害但需明确豁免或清理；勿重复操作' }
        elseif ("'$pkg -eq '"'com.android.virtualization.terminal') { Add-Row "'$pkg $layer $pol '"'NONE' 'pm -d 列出;enabled=0' "'$now '"'manifest 级默认禁用（库存态），非人工改动' '无操作；勿当作人工禁用处理' }
        else { Add-Row "'$pkg $layer $pol '"'DRIFT' "'$s14 $now '"'KEEP 包被禁用' '记录来源，勿擅自纠正' }
      } elseif ("'$inD128 -and $pkg -eq '"'com.hihonor.iaware') {
        Add-Row "'$pkg $layer $pol '"'DRIFT' 'u128=disabled(2)' "'$now '"'user128 disabled(2)，user0 正常' '记录；分身用户异常再处理；勿在 user0 禁用' 
      } else {
        Add-Row "'$pkg $layer $pol '"'COMPLETED' "'$s14 $now '"'enabled 正常，与 KEEP 相符' '无操作'
      }
    }
    '"'^KEEP_OR_REVIEW$'"' {
      if ("'$inD0) {
        if ($pkg -eq '"'com.huawei.android.pushagent') { Add-Row "'$pkg $layer $pol '"'DRIFT' 'enabled=3;u128=enabled' "'$now '"'user0 已禁用(3)、user128 仍启用、userWL 残留(10060)' '确认是否任务外历史改动；白名单条目陈旧，勿重复 disable' }
        else { Add-Row "'$pkg $layer $pol '"'DRIFT' "'$s14 $now '"'KEEP_OR_REVIEW 包被禁用' '记录来源' }
      } elseif ("'$inWl) {
        Add-Row $pkg $layer $pol '"'PENDING' "'$s14 $now '"'在 userWL，种子未定' '裁定后处置'
      } else {
        Add-Row "'$pkg $layer $pol '"'PENDING' "'$s14 $now '"'未裁定' '按需裁定'
      }
    }
    default {
      Add-Row "'$pkg $layer $pol '"'PENDING' "'$s14 $now '"'种子策略未识别/待裁定' '按需裁定'
    }
  }
}

# unseeded whitelist entries
foreach ("'$p in @('"'com.alibaba.android.rimet','com.tencent.wework')) {
  if ("'$wlPkg.ContainsKey($p)) { Add-Row $p '"'UNSEEDED' '（未收录）' 'DRIFT' 'userWL=yes' 'userWL=yes(uid '+"'$wlPkg[$p]+'"')' '种子外系统层白名单（S14 §5.4）' '补录种子或明确豁免' }
}
# xhs (in seed, NMB_REDUCED_IF_IDLE) already handled; add explicit note row only if needed
if ("'$wlPkg.ContainsKey('"'com.xingin.xhs')) { }

"'$tsv = $rows -join "`r`n"
[System.IO.File]::WriteAllText((Join-Path $outDir '"'STATE_DIFF.tsv'), "'$tsv + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
"ROWS=$($rows.Count)"
"WL_PKG_COUNT=$($wlPkg.Count)"; "NETPOL=$netpol"
Get-Content (Join-Path $outDir '"'STATE_DIFF.tsv') -TotalCount 8 -Encoding UTF8"

